export function suggestDiscipline(drawing){const {width:w,height:h,mask,ink,bounds:b}=drawing;let match=0,total=0,strokes=0;const cy=Math.round((b.y0+b.y1)/2);for(let y=Math.ceil(b.y0);y<Math.floor(b.y1);y++)for(let x=Math.ceil(b.x0);x<Math.floor(b.x1);x++){const i=y*w+x;if(ink[i])strokes++;const y2=2*cy-y;if(y2<0||y2>=h)continue;if(mask[i]||mask[y2*w+x]){total++;if(mask[i]&&mask[y2*w+x])match++;}}const symmetry=total?match/total:0,density=strokes/(b.width*b.height);return symmetry>.83&&density>.15?{domain:'mechanical',reason:'Se aprecia una envolvente casi simétrica y un corte denso. Revisa si corresponde a una pieza mecánica.',symmetry,density}:density<.12||(drawing.tones?.dark<.008&&drawing.tones?.lightGray>.1)?{domain:'exterior',reason:'El dibujo tiene trazos de alzado o esquema. Selecciona la disciplina antes de interpretarlo como una planta.',symmetry,density}:{domain:'interior',reason:'Selecciona la disciplina de la lámina.',symmetry,density};}
